class Node:
    def __init__(self, val):
        self.val = val
        self.next = None

def inorder(n):
    if n:
        inorder(n.left)
        print(n.val)
        inorder(n.right)

def bfs(start, adj):
    seen, q = {start}, [start]
    while q:
        v = q.pop(0)
        for w in adj[v]:
            if w not in seen:
                seen.add(w); q.append(w)
